package l10n

// CodexRuntime localizes file installation and independently verified runtime state.
func (l Localizer) CodexRuntime(key string) string {
	row, ok := codexRuntimeStrings[key]
	if !ok {
		return key
	}
	for i, language := range Languages() {
		if language == l.Language() {
			return row[i]
		}
	}
	return row[0]
}

